#include <stdio.h>

int solution(int first, int second, int N) {
    int card[N];
    card[0] = first;
    card[1] = second;
    int total = first + second;
    for (int i = 2; i < N; i++) {
        card[i] = (card[i - 1] + card[i - 2]) % 10;
        total += card[i];
    }
    return total;
}
